#include <vector>

using namespace std;

class Solution {
public:
    int numOfUnplacedFruits(vector<int>& fruits, vector<int>& baskets) {
        int n = fruits.size();
        int unplaced = 0;
        vector<int> b = baskets;
        for (int fruit : fruits) {
            bool placed = false;
            for (int j = 0; j < n; j++) {
                if (b[j] >= fruit) {
                    b[j] = 0;
                    placed = true;
                    break;
                }
            }
            if (!placed) unplaced++;
        }
        return unplaced;
    }
};

class Solution {
    public int numOfUnplacedFruits(int[] fruits, int[] baskets) {
        int n = fruits.length;
        int unplaced = 0;
        int[] b = baskets.clone();
        for (int fruit : fruits) {
            boolean placed = false;
            for (int j = 0; j < n; j++) {
                if (b[j] >= fruit) {
                    b[j] = 0;
                    placed = true;
                    break;
                }
            }
            if (!placed) unplaced++;
        }
        return unplaced;
    }
}

/**
 * @param {number[]} fruits
 * @param {number[]} baskets
 * @return {number}
 */
var numOfUnplacedFruits = function(fruits, baskets) {
    const n = fruits.length;
    let unplaced = 0;
    const b = [...baskets];
    for (const fruit of fruits) {
        let placed = false;
        for (let j = 0; j < n; j++) {
            if (b[j] >= fruit) {
                b[j] = 0;
                placed = true;
                break;
            }
        }
        if (!placed) unplaced++;
    }
    return unplaced;
};
